import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.D7Pdja0E.js";const p=JSON.parse('{"title":"데스크톱 앱","description":"","frontmatter":{},"headers":[],"relativePath":"01-getting-started/desktop.md","filePath":"01-getting-started/desktop.md","lastUpdated":1776160579000}'),l={name:"01-getting-started/desktop.md"};function i(s,t,d,n,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="데스크톱-앱" tabindex="-1">데스크톱 앱 <a class="header-anchor" href="#데스크톱-앱" aria-label="Permalink to &quot;데스크톱 앱&quot;">​</a></h1><p>Workhub 데스크톱 앱은 Windows용 네이티브 클라이언트입니다. 웹 브라우저 없이도 Workhub를 사용할 수 있으며, <strong>시스템 트레이 상주</strong>와 <strong>실시간 알림</strong>을 지원합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><table tabindex="0"><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td>시스템 트레이 상주</td><td>앱을 닫아도 트레이에서 계속 실행</td></tr><tr><td>Windows 토스트 알림</td><td>새 메시지, 멘션, 태스크 알림을 실시간 수신</td></tr><tr><td>자동 시작</td><td>Windows 시작 시 자동 실행 (설정 가능)</td></tr><tr><td>경량 실행</td><td>메모리 50~100MB, 설치 파일 약 10MB</td></tr></tbody></table><h2 id="설치" tabindex="-1">설치 <a class="header-anchor" href="#설치" aria-label="Permalink to &quot;설치&quot;">​</a></h2><ol><li>관리자로부터 전달받은 설치 파일(<code>WorkHub_x.x.x_x64-setup.exe</code>)을 실행합니다.</li><li>설치 마법사의 안내에 따라 진행합니다.</li><li>설치 완료 후 Workhub가 자동으로 실행됩니다.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>설치 시 Windows SmartScreen 경고가 표시될 수 있습니다. &quot;추가 정보&quot; → &quot;실행&quot;을 클릭하여 진행하세요. (코드 서명이 적용된 버전에서는 이 경고가 표시되지 않습니다.)</p></div><h2 id="사용법" tabindex="-1">사용법 <a class="header-anchor" href="#사용법" aria-label="Permalink to &quot;사용법&quot;">​</a></h2><h3 id="로그인" tabindex="-1">로그인 <a class="header-anchor" href="#로그인" aria-label="Permalink to &quot;로그인&quot;">​</a></h3><p>데스크톱 앱의 로그인 방법은 웹 버전과 동일합니다. 서버 URL이 사전 설정되어 있으므로 계정 정보만 입력하면 됩니다.</p><h3 id="시스템-트레이" tabindex="-1">시스템 트레이 <a class="header-anchor" href="#시스템-트레이" aria-label="Permalink to &quot;시스템 트레이&quot;">​</a></h3><p>데스크톱 앱은 창을 닫아도 종료되지 않고 **시스템 트레이(작업 표시줄 알림 영역)**에 상주합니다.</p><ul><li><strong>트레이 아이콘 클릭</strong> → 앱 창 열기</li><li><strong>트레이 아이콘 우클릭</strong> → 메뉴 표시 <ul><li><strong>WorkHub 열기</strong> — 앱 창을 전면으로 표시</li><li><strong>숨기기</strong> — 앱 창을 숨기고 트레이에만 상주</li><li><strong>종료</strong> — 앱 완전 종료</li></ul></li></ul><h3 id="실시간-알림" tabindex="-1">실시간 알림 <a class="header-anchor" href="#실시간-알림" aria-label="Permalink to &quot;실시간 알림&quot;">​</a></h3><p>로그인 상태에서는 SSE(Server-Sent Events)를 통해 서버의 알림을 실시간으로 수신합니다.</p><ul><li>앱이 <strong>숨김 상태이거나 비활성</strong> 상태일 때 Windows 토스트 알림이 표시됩니다.</li><li>앱이 <strong>활성 상태</strong>일 때는 앱 내 알림만 표시됩니다 (토스트 알림 없음).</li><li>알림을 클릭하면 해당 채널, DM, 또는 태스크로 바로 이동합니다.</li></ul><h3 id="웹-버전과의-차이" tabindex="-1">웹 버전과의 차이 <a class="header-anchor" href="#웹-버전과의-차이" aria-label="Permalink to &quot;웹 버전과의 차이&quot;">​</a></h3><p>데스크톱 앱의 기능은 웹 버전과 <strong>동일</strong>합니다. 추가적으로 다음을 지원합니다:</p><ul><li>시스템 트레이 상주 (백그라운드 실행)</li><li>Windows 네이티브 토스트 알림</li><li>OS 시작 시 자동 실행</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>채널, 메시지, 프로젝트, 태스크 등 모든 기능은 웹과 동일하게 동작합니다. 웹에서 작업한 내용은 데스크톱에서도 그대로 확인할 수 있습니다.</p></div>',20)])])}const b=a(l,[["render",i]]);export{p as __pageData,b as default};
